static String g_statusMessage;
static unsigned long g_statusUntil = 0;

// Simple I2C scanner to help debug display issues on the selected TwoWire bus
static void scanI2C(TwoWire &tw) {
  Serial.println(F("\nScanning I2C bus for devices..."));
  for(uint8_t addr = 1; addr < 127; addr++) {
    tw.beginTransmission(addr);
    uint8_t error = tw.endTransmission();
    if(error == 0) {
      Serial.print(F("I2C device found at address 0x"));
      if(addr < 16) Serial.print("0");
      Serial.println(addr, HEX);
    }
  }
  Serial.println(F("Scan complete.\n"));
}

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire1, OLED_RESET);

void setupDisplay() {
  TwoWire &tw = Wire1;

  // Initialize I2C with the correct pins for RP2040
  tw.setSDA(I2C_SDA_PIN);
  tw.setSCL(I2C_SCL_PIN);
  tw.begin();
  tw.setClock(400000); // 400kHz
  
  // Scan I2C bus to see if display is detected
  scanI2C(tw);
  
  Serial.print(F("Initializing display at address 0x"));
  Serial.println(SCREEN_ADDRESS, HEX);

  if(!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println(F("SSD1306 allocation failed"));
    for(;;);
  }
  display.clearDisplay();
}

void drawSplashScreen() {
  Serial.println("Drawing splash screen...");
  unsigned long start = millis();
  unsigned long duration = 2000; // Reduced from 5000
  unsigned long interval = 500;  // Reduced from 2000
  int count = 0;
  while(millis() - start < duration) {
    display.clearDisplay();
    if (count % 2 == 0) {
      display.drawBitmap(6,10, logo_1, 117, 42, SSD1306_WHITE);
    } else {
      display.drawBitmap(6,10, logo_2, 117, 42, SSD1306_WHITE);
    }
    display.display();
    delay(interval);
    count++;
  }
  
  // Clear display and show initial state after splash
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print("Ready");
  display.display();
  delay(500);
  
  Serial.println("Splash screen complete");
}

void updateDisplay() {
  static unsigned long lastDebug = 0;
  bool shouldDebug = (millis() - lastDebug > 2000);
  
  String chordName = getCurrentChordName();
  
  if (shouldDebug) {
    Serial.print("updateDisplay() called | chord='");
    Serial.print(chordName);
    Serial.println("'");
    lastDebug = millis();
  }
  
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  // Always show chord info, with status overlaid at top if active
  bool hasStatus = (g_statusMessage.length() > 0 && millis() < g_statusUntil);
  
  // Top line: status message OR scale info
  display.setTextSize(1);
  display.setCursor(0, 0);
  if (hasStatus) {
    display.print(g_statusMessage);
  } else {
    display.print(getNoteName(getCurrentRootNote()));
    display.print(" ");
    display.print(getCurrentScaleName());
  }
  
  // Middle: chord name (always shown)
  display.setTextSize(2);
  display.setCursor(10, 25);
  if (chordName.length() > 0) {
    display.print(chordName);
  } else {
    display.print("---");  // Show something when no chord active
  }
  
  if (shouldDebug) {
    Serial.print("Drawing chord: '");
    Serial.print(chordName.length() > 0 ? chordName : "---");
    Serial.println("'");
  }
  
  // Bottom line: mode indicators
  display.setTextSize(1);
  display.setCursor(0, 56);
  if (isBassMode()) {
    display.print("[B] ");
  }
  if (isAutoVoicingMode()) {
    display.print("[AV] ");
  }
  
  // Show current inversion if not using auto-voicing
  int inv = getCurrentInversion();
  if (inv > 0 && !isAutoVoicingMode()) {
    display.print("Inv:");
    display.print(inv);
  }
  
  // Show chord history (compact, degrees only)
  int histCount = getChordHistoryCount();
  if (histCount > 0) {
    display.setCursor(0, 48);
    display.print("< ");
    
    int toShow = min(3, histCount);
    for (int i = 0; i < toShow; i++) {
      if (i > 0) display.print("-");
      int deg = getChordHistoryDegree(i);
      if (deg >= 0 && deg <= 6) {
        display.print(deg);
      }
    }
  }
  
  if (shouldDebug) {
    Serial.println(" display.display() done");
  }
  
  display.display();
}

void showStatus(String message, unsigned long durationMs) {
  // Set timed message - it will be shown on the next updateDisplay() call
  g_statusMessage = message;
  g_statusUntil = millis() + durationMs;
}

String getNoteName(int noteNumber) {
  const char* noteNames[] = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
  return noteNames[noteNumber % 12];
}